if not any(p==demo2 for p in pairs): pairs.append(demo2)
program='''def transform(grid):
    n=len(grid)
    q=(n+1)//2
    out=[[7]*n for _ in range(n)]
    for br in (0,q):
        for bc in (0,q):
            colors={grid[r][c] for r in range(br,br+q) for c in range(bc,bc+q)}-{7}
            for color in colors:
                pts=[(r,c) for r in range(br,br+q) for c in range(bc,bc+q) if grid[r][c]==color]
                if max(r for r,c in pts)-min(r for r,c in pts)+1==q:
                    for i in range(q):
                        c=bc+i if br==bc else bc+q-1-i
                        out[br+i][c]=color
                    return out
    return out
'''
ns={};exec(program,ns)
checks=[ns['transform'](p['input'])==p['output'] for p in pairs]
